115		// Collect imports from all template elements using the ImportRequirer interface
116		// This is extensible - any type that implements ImportRequirer will have its imports added
117	
118		// Check concat helpers (list.Concat requires "list")
119		for _, helper := range tpl.GetConcatHelpers() {
