123		// Check struct array helpers
124		for _, helper := range tpl.GetStructArrayHelpers() {
125			g.collectImportsFromValue(helper)
126		}
127	
128		// Check dedupe helpers
129		for _, helper := range tpl.GetDedupeHelpers() {
130			g.collectImportsFromValue(helper)
131		}
132	
133		// Check helper variables (before and after output)
134		for _, helper := range tpl.GetHelpersBeforeOutput() {
135			g.collectImportsFromValue(helper)
136			g.collectImportsFromValue(helper.Collection())
137		}
138		for _, helper := range tpl.GetHelpersAfterOutput() {
139			g.collectImportsFromValue(helper)
140			g.collectImportsFromValue(helper.Collection())
141		}
142	
143		// Check parameters for import requirements (e.g. StringParam with MinLen/MaxLen needs "strings")
144		for _, param := range c.GetParams() {
145			if ir, ok := param.(ImportRequirer); ok {
146				for _, imp := range ir.RequiredImports() {
147					g.addImportIfMissing(imp)
148				}
149			}
150		}
151	
152		// Check resource operations in output
153		if output := tpl.GetOutput(); output != nil {
154			g.collectImportsFromResource(output)
155		}
156	
157		// Check resource operations in outputs
158		for _, res := range tpl.GetOutputs() {
159			g.collectImportsFromResource(res)
160		}
161	}
