	if guard := v.GuardCondition(); guard != nil {
		// OnlyWhen(AbsentOrEmpty) duplicates the entire validator body under
		// each branch; a plain guard wraps the body in a single if block.
		if aoe, ok := guard.(*AbsentOrEmptyCondition); ok {
			for _, branch := range aoe.Branches() {
				g.writeValidatorGuarded(sb, v, branch, depth)
			}
			return
		}
		g.writeValidatorGuarded(sb, v, guard, depth)
		return
	}
	g.writeValidatorBody(sb, v, depth)
}

